using Lastlight.Core;
using System.Text.Json;
public static class RegionAcceptance
{
 public static void Run(Definitions d,string output,string assets)
 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Command(World w,WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,c.Text+": "+r.Message);}void Until(World w,Func<bool> done,int limit,string label){for(int i=0;i<limit&&!done();i++)w.Step(d);Require(done(),label+" stalled at "+w.Tick+"; "+string.Join(" / ",w.Autonomy.Jobs.Select(j=>j.Kind+":"+j.Sources.Count)));w.Validate(d);}void Save(string name,World w,string tab="World"){SaveStore.Write(Path.Combine(output,name+".lastlight"),w,new ViewState{CameraX=64,CameraY=64,OpenTab=tab},d);}
  var w=LivingWorldGenerator.Create(d,74219);var identical=LivingWorldGenerator.Create(d,74219);Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(identical),"Generated region not reproducible.");Require(SaveStore.Fingerprint(w)!=SaveStore.Fingerprint(LivingWorldGenerator.Create(d,74220)),"Different regional seeds match.");Require(w.Region.Tiles.Count==144&&w.Region.Factions.Count==6&&w.Region.Sites.Count==13&&w.Region.History.Any(h=>h.PersonId!=0&&h.SiteId!=0)&&w.Region.History.Any(h=>h.ArtifactId!=0),"Generation/history links missing.");Save("living-world",w);Console.WriteLine("PASS G01/G02: seeded geography/climate/roads/cultures, six reserve-bearing factions, named people and linked era/site/artifact history");
  long leader=w.Colony.People.Keys.First();var members=w.Colony.People.Keys.Take(2).ToArray();var quest=w.Region.Quests.First(q=>q.Kind=="Recovery");Command(w,new(CommandKind.RegionAction,TargetId:quest.Id,Quantity:1,Text:"quest"));var meal=w.Apply(new(CommandKind.Spawn,DefinitionId:"meal",X:62,Y:67,Quantity:8),d);Require(meal.Accepted,meal.Message);int beforeMeals=w.Resources("meal").Total,beforeBrass=w.Resources("brass").Total;
  Command(w,new(CommandKind.RegionAction,leader,string.Join(',',members),TargetId:quest.SiteId,Quantity:2,Text:"depart"));var party=w.Region.Parties.Last();Until(w,()=>party.State=="Outbound",12000,"real provisioning");Require(party.Cargo.GetValueOrDefault("meal")==4&&party.Cargo.GetValueOrDefault("brass")==10&&party.Cargo.GetValueOrDefault("medicine")==2,"Packed provisions not exact.");Require(w.Region.Absent.SetEquals(members)&&members.All(id=>!w.CanAct(id)),"Travelers still active at home.");Save("expedition-outbound",w);
  var restored=SaveStore.Read(Path.Combine(output,"expedition-outbound.lastlight"),d).World;Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(restored),"Outbound party reload differs.");Steps(w,900);Steps(restored,900);Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(restored),"Travel continuation diverged.");Until(w,()=>party.State=="AtSite",12000,"site arrival");Require(w.Levels==4&&members.All(id=>w.Find(id)!.Z==3)&&w.Region.Absent.Count==0,"Tactical site/actors not instantiated.");
  var artifact=w.Region.Artifacts.First(a=>a.Id==quest.ArtifactId);var item=w.Find(artifact.LocalEntityId)!;Require(!w.Apply(new(CommandKind.RegionAction,leader,TargetId:artifact.Id,Text:"take"),d).Accepted,"Remote artifact pickup accepted.");Command(w,new(CommandKind.MoveDrafted,leader,X:item.X-1,Y:item.Y,Z:item.Z));Until(w,()=>Math.Abs(w.Find(leader)!.X-item.X)+Math.Abs(w.Find(leader)!.Y-item.Y)<=1,6000,"drafted expedition movement");Command(w,new(CommandKind.RegionAction,leader,TargetId:artifact.Id,Text:"take"));Require(artifact.Custody=="Party"&&artifact.LocalEntityId==0&&party.Artifacts.Contains(artifact.Id),"Unique artifact not transferred to party.");Require(!w.Apply(new(CommandKind.RegionAction,leader,TargetId:artifact.Id,Text:"take"),d).Accepted,"Artifact duplicated by repeated pickup.");Save("artifact-recovered",w);
  Console.WriteLine("PASS G03: physical packing, absent home workers, saved travel, authored history-based site, ordinary drafted movement and adjacent unique recovery");
  var town=w.Region.Sites.First(s=>s.Kind=="Town"&&s.FactionId==quest.FactionId);Command(w,new(CommandKind.RegionAction,TargetId:party.Id,Quantity:(int)town.Id,Text:"travel"));Until(w,()=>party.State=="AtSite"&&party.SiteId==town.Id,12000,"town arrival");var counter=w.Find(town.MarketId)!;Command(w,new(CommandKind.MoveDrafted,leader,X:counter.X-1,Y:counter.Y,Z:counter.Z));Until(w,()=>Math.Abs(w.Find(leader)!.X-counter.X)+Math.Abs(w.Find(leader)!.Y-counter.Y)<=2,6000,"counter approach");
  var faction=w.Region.Factions.First(f=>f.Id==quest.FactionId);int reserveMedicine=faction.Reserves["medicine"];Command(w,new(CommandKind.RegionAction,leader,TargetId:party.Id,Quantity:(int)quest.Id,Text:"complete"));Require(quest.Status=="Completed"&&artifact.Custody=="Faction"&&!party.Artifacts.Contains(artifact.Id)&&faction.Reserves["medicine"]==reserveMedicine-3,"Restitution/reward did not conserve identity/reserves.");Command(w,new(CommandKind.RegionAction,leader,"Safe passage",TargetId:party.Id,Text:"treaty"));Command(w,new(CommandKind.RegionAction,leader,"medicine",TargetId:party.Id,Quantity:1,Text:"buy"));Require(faction.Reserves["medicine"]==reserveMedicine-4&&w.Region.TradeTransactions==1,"Trade fabricated goods.");Save("treaty-and-restitution",w,"Factions");
  restored=SaveStore.Read(Path.Combine(output,"treaty-and-restitution.lastlight"),d).World;Require(restored.HasTreaty(faction.Id,"Safe passage")&&restored.Region.Artifacts.Single(a=>a.Id==artifact.Id).Custody=="Faction"&&restored.Region.Quests.Single(q=>q.Id==quest.Id).Status=="Completed","EXIT GATE: treaty, expedition or artifact transfer lost after reload.");Console.WriteLine("PASS G04/G05 EXIT GATE: town-counter trade, reserve-backed quest restitution, relationship consequences and signed treaty/artifact custody survive reload");
  Command(w,new(CommandKind.RegionAction,TargetId:party.Id,Text:"return"));Until(w,()=>party.State=="Returned",12000,"return home");Require(members.All(id=>w.Find(id)!.Z==0&&!w.Colony.People[id].Drafted)&&party.Cargo.Count==0&&w.Region.Absent.Count==0,"Party/cargo not restored physically home.");Save("expedition-returned",w);Steps(w,World.TicksPerDay*3);w.Validate(d);Require(w.Colony.People.Keys.All(id=>w.Body(id) is {Dead:false}),"Living-world camp lost a resident during regional progression.");Save("living-world-day-three",w);Console.WriteLine("PASS G persistent play: real return/unloading, home work resumes, three further days of region/colony simulation and surviving residents");
  string fixture=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(assets))!,"../../../tests/fixtures/physical-depth-day-three.lastlight");var raw=JsonSerializer.Deserialize<SaveEnvelope>(File.ReadAllText(fixture),JsonFormat.Options)!;Require(raw.FormatVersion==6,"F migration fixture changed.");var old=SaveStore.Read(fixture,d).World;Require(!old.Region.Enabled&&old.Levels==3,"Migration enabled regional simulation or altered map.");old.Validate(d);Console.WriteLine("PASS G migration: authentic format-6 F colony preserves existing map and physical state with regional simulation opt-in");
  var invalid=LivingWorldGenerator.Create(d,74219);invalid.Region.Factions[0].Reserves["meal"]=-1;bool rejected=false;try{invalid.Validate(d);}catch(InvalidDataException){rejected=true;}Require(rejected,"Negative regional stock accepted.");Console.WriteLine("PASS G integrity: bounded IDs, references, custody, routes, inventories, treaty terms and malformed stock validation");
 }
}
